"""Refresh the offline oracle and embedded resources with python3 -B testdata/generate.py."""
import csv
import itertools
import json
import sys
import unicodedata
from pathlib import Path
from tempfile import TemporaryDirectory
from zipfile import ZipFile

HERE = Path(__file__).resolve().parent
PACKAGE = HERE.parent
sys.path.insert(0, str(PACKAGE.parents[3] / "deploy/monthly-usage"))
import workbook

case = json.loads((HERE / "case.json").read_text())
with TemporaryDirectory() as tmp:
    csv_path = Path(tmp) / "usage.csv"
    with csv_path.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.writer(handle)
        writer.writerow(workbook.COLUMNS)
        writer.writerows(case["rows"])
    workbook.build_workbook(HERE / "reference.xlsx", "2024-02", {case["site"]: csv_path},
                            registered=case["registered"])

# Only the root relationship and styles are independent of the set of platforms.
with ZipFile(HERE / "reference.xlsx") as book:
    for source, name in [
        ("_rels/.rels", "root-rels.xml"), ("xl/styles.xml", "styles.xml"),
    ]:
        (PACKAGE / "parts" / name).write_bytes(book.read(source))

# Freeze the reference interpreter's combining classes and East Asian widths for layout.
with (PACKAGE / "width_table.go").open("w") as out:
    print("// Code generated by testdata/generate.py (Unicode " + unicodedata.unidata_version +
          "). DO NOT EDIT.\n\npackage monthlyusage\n", file=out)
    print("var widthRanges = [...]struct {\n\tfirst, last rune\n\twidth       int\n}{", file=out)
    for width, group in itertools.groupby(range(sys.maxunicode + 1),
                                          key=lambda cp: workbook._line_width(chr(cp))):
        first = next(group)
        last = first
        for last in group:
            pass
        if width != 1:
            print(f"\t{{0x{first:04X}, 0x{last:04X}, {width}}},", file=out)
    print("}", file=out)
